import{_ as d,c as e,o,b2 as r}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"功能模块总览","description":"","frontmatter":{},"headers":[],"relativePath":"docs/backend/modules/index.md","filePath":"docs/backend/modules/index.md"}'),a={name:"docs/backend/modules/index.md"};function l(c,t,h,n,i,s){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="功能模块总览" tabindex="-1">功能模块总览 <a class="header-anchor vp-link" href="#功能模块总览" aria-label="Permalink to &quot;功能模块总览&quot;">​</a></h1><p>本文按 <strong>Controller 包</strong> 索引 quickboot-web 已实现能力。接口路径以 Swagger 为准。</p><h2 id="认证与会话-web-auth" tabindex="-1">认证与会话（<code>web.auth</code>） <a class="header-anchor vp-link" href="#认证与会话-web-auth" aria-label="Permalink to &quot;认证与会话（`web.auth`）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>类</th><th>路径前缀</th><th>能力</th></tr></thead><tbody><tr><td><code>AuthController</code></td><td><code>/</code></td><td>登录、登出、<code>getInfo</code>、<code>getRouters</code>、验证码相关</td></tr><tr><td><code>QrcodeImageController</code></td><td>—</td><td>二维码图片</td></tr></tbody></table></div><h2 id="oauth2-web-auth-oauth2" tabindex="-1">OAuth2（<code>web.auth.oauth2</code>） <a class="header-anchor vp-link" href="#oauth2-web-auth-oauth2" aria-label="Permalink to &quot;OAuth2（`web.auth.oauth2`）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>类</th><th>能力</th></tr></thead><tbody><tr><td><code>SaOAuth2ServerController</code></td><td>授权服务器 <code>/oauth2/*</code>（Sa-Token）</td></tr><tr><td><code>OAuth2ClientController</code></td><td>第三方 IdP：<code>/oauth2/client/authorize</code>、<code>callback/{provider}</code></td></tr><tr><td><code>OAuth2LoginProvidersController</code></td><td>登录页可用 IdP 列表 <code>/oauth/login/providers</code></td></tr><tr><td><code>OpenApiUserinfoController</code></td><td>Open API <code>/open-api/v1/userinfo</code></td></tr><tr><td><code>SysOauthClientController</code></td><td>管理端 OAuth 客户端 CRUD</td></tr><tr><td><code>SysOauthProviderController</code></td><td>管理端外部 IdP 配置 CRUD</td></tr></tbody></table></div><p>对接说明见 <a href="./oauth2.html" class="vp-link">OAuth2 集成</a>。</p><h2 id="系统管理-web-system" tabindex="-1">系统管理（<code>web.system</code>） <a class="header-anchor vp-link" href="#系统管理-web-system" aria-label="Permalink to &quot;系统管理（`web.system`）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>模块</th><th>Controller</th><th>说明</th></tr></thead><tbody><tr><td>用户</td><td><code>SysUserController</code></td><td>用户 CRUD、导入导出、角色分配</td></tr><tr><td>角色</td><td><code>SysRoleController</code></td><td>角色、菜单权限、<strong>数据权限</strong></td></tr><tr><td>菜单</td><td><code>SysMenuController</code></td><td>菜单树、路由元数据</td></tr><tr><td>部门</td><td><code>SysDeptController</code></td><td>部门树</td></tr><tr><td>字典类型</td><td><code>DictTypeController</code></td><td>字典类型</td></tr><tr><td>字典数据</td><td><code>DictDataController</code></td><td>字典项</td></tr><tr><td>参数配置</td><td><code>SysConfigController</code></td><td>系统参数键值</td></tr><tr><td>通知公告</td><td><code>SysNoticeController</code></td><td>公告（富文本 XSS 过滤）</td></tr></tbody></table></div><h2 id="监控与调度-web-monitor" tabindex="-1">监控与调度（<code>web.monitor</code>） <a class="header-anchor vp-link" href="#监控与调度-web-monitor" aria-label="Permalink to &quot;监控与调度（`web.monitor`）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>模块</th><th>Controller</th><th>说明</th></tr></thead><tbody><tr><td>操作日志</td><td><code>SysOperLogController</code></td><td>AOP 采集、查询、导出</td></tr><tr><td>登录日志</td><td><code>SysLogininforController</code></td><td>登录成功/失败记录</td></tr><tr><td>在线用户</td><td><code>SysUserOnlineController</code></td><td>会话列表、强退</td></tr><tr><td>定时任务</td><td><code>SysJobController</code></td><td>Quartz 任务 CRUD、启停、立即执行</td></tr><tr><td>任务日志</td><td><code>SysJobLogController</code></td><td>执行历史</td></tr></tbody></table></div><h2 id="开发工具-web-tool" tabindex="-1">开发工具（<code>web.tool</code>） <a class="header-anchor vp-link" href="#开发工具-web-tool" aria-label="Permalink to &quot;开发工具（`web.tool`）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>模块</th><th>Controller</th><th>说明</th></tr></thead><tbody><tr><td>代码生成</td><td><code>GenController</code></td><td>表导入、配置、预览、生成 ZIP；MyBatis-Plus Generator + FreeMarker</td></tr></tbody></table></div><p>配置项：<code>quickboot.gen.*</code>（作者、包名、模块名等）。</p><hr><h2 id="quickboot-common-能力索引" tabindex="-1">quickboot-common 能力索引 <a class="header-anchor vp-link" href="#quickboot-common-能力索引" aria-label="Permalink to &quot;quickboot-common 能力索引&quot;">​</a></h2><p>与业务模块正交的横切能力（实现于 common，由 web 引用）：</p><div class="vp-table"><table><thead><tr><th>能力</th><th>包/类（示意）</th></tr></thead><tbody><tr><td>统一响应与分页</td><td><code>api.R</code>、<code>PageInfo</code></td></tr><tr><td>异常与错误码</td><td><code>exception.*</code></td></tr><tr><td>国际化</td><td><code>i18n.I18nUtil</code></td></tr><tr><td>缓存</td><td><code>cache</code> 动态 TTL</td></tr><tr><td>Excel</td><td><code>excel.EasyExcelSupport</code> 等</td></tr><tr><td>字段脱敏</td><td><code>desensitization</code></td></tr><tr><td>验证码</td><td><code>captcha</code></td></tr><tr><td>文件存储</td><td><code>file.FileTemplate</code></td></tr><tr><td>操作日志</td><td><code>monitor.operlog</code></td></tr><tr><td>Web 防火墙</td><td><code>security.firewall.*</code></td></tr></tbody></table></div><p>详细使用文档规划见 <a href="./../../guide/capabilities-outline.html" class="vp-link">能力文档大纲</a> 第三节「通用组件」。</p><hr><h2 id="数据库迁移索引" tabindex="-1">数据库迁移索引 <a class="header-anchor vp-link" href="#数据库迁移索引" aria-label="Permalink to &quot;数据库迁移索引&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>版本</th><th>文件</th><th>用途</th></tr></thead><tbody><tr><td>V1</td><td>baseline</td><td>Flyway 基线</td></tr><tr><td>V2–V7</td><td>sys_dept … sys_notice</td><td>部门、字典、配置、菜单、公告</td></tr><tr><td>V8–V15</td><td>各类 menu/seed</td><td>用户/配置/角色等菜单与演示数据</td></tr><tr><td>V16–V17</td><td>oper_log, logininfor</td><td>操作日志、登录日志</td></tr><tr><td>V18</td><td>gen_table</td><td>代码生成元数据</td></tr><tr><td>V19–V22</td><td>sys_job, quartz</td><td>定时任务与 Quartz 修正</td></tr><tr><td>V23–V24</td><td>dict_menu, online_menu</td><td>字典、在线用户菜单</td></tr><tr><td>V25–V31</td><td>oauth2_*</td><td>OAuth2 表、菜单、quick-ui 客户端、API 路径授权、签名校验</td></tr></tbody></table></div><p>脚本路径：<code>quickboot-web/src/main/resources/db/migration/</code>。</p><hr><h2 id="模块文档" tabindex="-1">模块文档 <a class="header-anchor vp-link" href="#模块文档" aria-label="Permalink to &quot;模块文档&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="./user-management.html" class="vp-link">用户管理</a></td><td>用户 CRUD、导入导出</td></tr><tr><td><a href="./permission-management.html" class="vp-link">权限管理</a></td><td>菜单、角色、数据权限</td></tr><tr><td><a href="./system-management.html" class="vp-link">系统配置</a></td><td>部门、字典、参数、公告</td></tr><tr><td><a href="./monitor-audit.html" class="vp-link">监控审计</a></td><td>操作/登录日志、在线用户</td></tr><tr><td><a href="./job-scheduler.html" class="vp-link">定时任务</a></td><td>Quartz</td></tr><tr><td><a href="./codegen.html" class="vp-link">代码生成</a></td><td>表导入与 ZIP 生成</td></tr><tr><td><a href="./security-module.html" class="vp-link">安全防护</a></td><td>Web 防火墙</td></tr><tr><td><a href="./client-management.html" class="vp-link">客户端管理</a></td><td>OAuth Client + HMAC</td></tr><tr><td><a href="./oauth2.html" class="vp-link">OAuth2 集成</a></td><td>AS / 联邦 / Open API</td></tr></tbody></table></div><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor vp-link" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../index.html" class="vp-link">后端概述</a></li><li><a href="./../api/index.html" class="vp-link">接口规范</a></li></ul>',28)])])}const p=d(a,[["render",l]]);export{u as __pageData,p as default};
